package com.performance.demo;

import java.util.ArrayList;
import java.util.List;

public class MemoryAndBoxingDemo {

    public static void main(String[] args) {
        // 1. Silent Auto-boxing in Hot Loops (Performance Anti-Pattern)
        long startTime = System.nanoTime();
        Long sum = 0L; // Wrapper object
        for (long i = 0; i < 1_000_000; i++) {
            // Auto-unboxes 'sum', adds 'i', then auto-boxes back into a NEW 'Long' object.
            // This creates 1,000,000 short-lived Long instances on the heap!
            sum += i; 
        }
        long endTime = System.nanoTime();
        System.out.println("Boxed sum execution time: " + (endTime - startTime) / 1_000_000 + " ms");

        // 2. Optimized Primitive Loop
        startTime = System.nanoTime();
        long primitiveSum = 0L; // Pure primitive
        for (long i = 0; i < 1_000_000; i++) {
            primitiveSum += i; // No allocation, no boxing, pure CPU register/stack operations
        }
        endTime = System.nanoTime();
        System.out.println("Primitive sum execution time: " + (endTime - startTime) / 1_000_000 + " ms");

        // 3. The Integer Cache Trap
        Integer cached1 = 127;
        Integer cached2 = 127;
        System.out.println("Cached (127 == 127): " + (cached1 == cached2)); // Prints true

        Integer nonCached1 = 128;
        Integer nonCached2 = 128;
        System.out.println("Non-cached (128 == 128): " + (nonCached1 == nonCached2)); // Prints false (different heap objects)
        System.out.println("Correct comparison (.equals): " + nonCached1.equals(nonCached2)); // Prints true
    }
}
